123	// kernel function calling entrance
124	int32_t aclshmemi_prepare_and_post_rma(const char *api_name, aclshmemi_op_t desc, bool is_nbi, uint8_t *dst, uint8_t *src,
125	                                    size_t n_elems, size_t elem_bytes, int pe, uint8_t *sig_addr, int32_t signal,
126	                                    int sig_op, ptrdiff_t lstride, ptrdiff_t rstride, aclrtStream acl_strm,
127	                                    size_t block_size)
128	{
129	    if (is_nbi) {
130	        switch (desc) {
131	            case ACLSHMEMI_OP_PUT:
132	                aclshmemi_putmem_nbi<<<block_size, 0, acl_strm>>>(dst, src, n_elems * elem_bytes, pe);
133	                break;
134	            case ACLSHMEMI_OP_GET:
135	                aclshmemi_getmem_nbi<<<block_size, 0, acl_strm>>>(dst, src, n_elems * elem_bytes, pe);
136	                break;
137	            case ACLSHMEMI_OP_PUT_SIGNAL:
138	                aclshmemi_putmem_signal_nbi<<<block_size, 0, acl_strm>>>(dst, src, n_elems * elem_bytes, sig_addr,
139	                                                                      signal, sig_op, pe);
140	                break;
141	            case ACLSHMEMI_OP_QUIET:
142	                k_aclshmemi_quiet<<<block_size, 0, acl_strm>>>();
143	                break;
144	            default:
145	                break;
146	        }
147	    } else {
148	        bool contiguous = lstride == 1 && rstride == 1;
149	        if (contiguous) {
150	            switch (desc) {
151	                case ACLSHMEMI_OP_PUT:
152	                    aclshmemi_putmem<<<block_size, 0, acl_strm>>>(dst, src, n_elems * elem_bytes, pe);
153	                    break;
154	                case ACLSHMEMI_OP_GET:
155	                    aclshmemi_getmem<<<block_size, 0, acl_strm>>>(dst, src, n_elems * elem_bytes, pe);
156	                    break;
157	                case ACLSHMEMI_OP_PUT_SIGNAL:
158	                    aclshmemi_putmem_signal<<<block_size, 0, acl_strm>>>(dst, src, n_elems * elem_bytes, sig_addr, signal,
159	                                                                    sig_op, pe);
160	                    break;
161	                case ACLSHMEMI_OP_QUIET:
162	                    k_aclshmemi_quiet<<<block_size, 0, acl_strm>>>();
163	                    break;
164	                default:
165	                    break;
166	            }
167	        } else {
168	            non_contiguous_copy_param copy_params {static_cast<uint32_t>(n_elems),
169	                                                   static_cast<uint32_t>(elem_bytes),
170	                                                   static_cast<uint32_t>(rstride),
171	                                                   static_cast<uint32_t>(lstride)};
172	            switch (desc) {
173	                case ACLSHMEMI_OP_PUT:
174	                    aclshmemi_putbits<<<block_size, 0, acl_strm>>>(dst, src, copy_params, pe);
175	                    break;
176	                case ACLSHMEMI_OP_GET:
177	                    aclshmemi_getbits<<<block_size, 0, acl_strm>>>(dst, src, copy_params, pe);
178	                    break;
179	                case ACLSHMEMI_OP_QUIET:
180	                    k_aclshmemi_quiet<<<block_size, 0, acl_strm>>>();
181	                    break;
182	                default:
183	                    break;
184	            }
185	        }
186	    }
187	    return 0;
188	}
